function roleConfigError(context, failure, h) {
  // Never forward raw service errors or Sheet values: even upstream exceptions
  // can contain URLs, credential identifiers, and complete configuration data.
  const allowedTypes = ['ROLE_CONFIG_INVALID', 'ROLE_CONFIG_NO_ADMIN'];
  const type = failure.role_config_ok === false && allowedTypes.includes(failure.error_type)
    ? failure.error_type : 'ROLE_CONFIG_UNAVAILABLE';
  const rowMatch = /^CONFIG_ROLE invalid at row (\d+|unknown)\.$/.exec(String(failure.error_detail || ''));
  const detail = type === 'ROLE_CONFIG_NO_ADMIN' ? 'CONFIG_ROLE has no ACTIVE ADMIN.'
    : type === 'ROLE_CONFIG_INVALID' ? 'CONFIG_ROLE invalid at row ' + (rowMatch?.[1] || 'unknown') + '.'
      : 'CONFIG_ROLE read or validation unavailable. Check the role-read node and Sheet access.';
  const errorRow = { id_error: 'ERR-ROLE-' + context.id_mua + '-' + String(context.update_id ?? context.callback_query_id ?? ''),
    ngay: context.ngay, thoi_gian: new Date().toISOString(), telegram_user_id: context.user_id,
    telegram_chat_id: context.chat_id, message_id: String(context.message_id ?? ''),
    id_mua: '', file_id: '', error_type: type, error_detail: detail, raw_ocr: '', trang_thai: 'OPEN' };
  return { ...context, role_config_ok: false, is_admin: false, is_buyer: false,
    error_row: errorRow,
    reply_text: '⚠️ Hệ thống phân quyền đang tạm lỗi. Tôi chưa thay đổi dữ liệu. Vui lòng thử lại sau hoặc liên hệ quản trị.',
