  const visual = mode === 'RESCUE'
    ? 'Đây là lượt OCR cứu hộ độ phân giải cao. Hãy kiểm tra ảnh như khi xoay 0°, 90°, 180° và 270°, chọn chiều dễ đọc nhất, cân nhắc ảnh nghiêng/phối cảnh/bóng/chữ viết tay. Chỉ trích xuất nội dung nhìn thấy; không đoán chữ số bị che hoặc mất nét.'
    : 'Đọc hóa đơn mua thực phẩm Việt Nam. Trước khi trích xuất, xác định chiều đọc phù hợp và lưu ý ảnh có thể bị xoay hoặc nghiêng. Chỉ trích xuất nội dung nhìn thấy; không đoán dữ liệu.';
  return visual + '\n' + schema;
}

async function prepareGemini(x, incoming, helpers, h) {
  try {
    if (incoming.json?.error) throw new Error('Không tải được ảnh từ Telegram.');
    const supported = ['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif'];
    const mime = x.file_mime || incoming.binary?.data?.mimeType;
    if (!supported.includes(mime)) throw new Error('File không phải định dạng ảnh được hỗ trợ. Hãy gửi JPG/PNG.');
    const buffer = await helpers.getBinaryDataBuffer(0, 'data');
    if (!buffer?.length || buffer.length > 14 * 1024 * 1024) throw new Error('Ảnh trống hoặc quá lớn. Hãy gửi JPG/PNG dưới 14 MB.');
    const prompt = ocrPrompt('PRIMARY');
    return { ...x, request_ready: true, gemini_body: {
      contents: [{ role: 'user', parts: [{ text: prompt }, { inline_data: { mime_type: mime, data: buffer.toString('base64') }, media_resolution: { level: 'MEDIA_RESOLUTION_MEDIUM' } }] }],
      generationConfig: { responseMimeType: 'application/json', maxOutputTokens: 2048, thinkingConfig: { thinkingLevel: 'MINIMAL' } },
    } };
  } catch (error) {
    return { ...x, request_ready: false, ocr_ok: false, error_type: 'IMAGE_DOWNLOAD_OR_FORMAT',
      failure_category: 'IMAGE_INPUT', error_detail: 'Không thể chuẩn bị ảnh hợp lệ cho OCR.', raw_ocr: '' };
  }
}
