  if (!context?.is_buyer || !['MUA_TT_XN', 'MUA_CN_XN'].includes(action)) return noUpdate;
  const idMua = String(context.id_mua ?? '');
  if (!/^[A-Za-z0-9_-]{1,50}$/.test(idMua) || !Array.isArray(rows)) return noUpdate;
