  const status = String(row?.trang_thai ?? '').trim().toUpperCase();
  const payment = String(row?.trang_thai_thanh_toan ?? '').trim().toUpperCase();
  if (status !== 'ACTIVE' || payment !== 'CHO_PHAN_LOAI') return noUpdate;
  const instant = new Date(now);
  if (Number.isNaN(instant.getTime())) return noUpdate;
