  const day = `${part('year')}-${part('month')}-${part('day')}`;
  return {
    can_update: true,
    patch: {
      id_mua: idMua,
      trang_thai_thanh_toan: action === 'MUA_TT_XN' ? 'DA_THANH_TOAN' : 'CONG_NO_CHUA_TRA',
      ngay_hach_toan: day,
      nguoi_phan_loai: String(context.user_id ?? ''),
