  const label = route === 'MUA_SUA' ? 'Đồng ý sửa' : 'Đồng ý xóa';
  if (route === 'MUA_SUA' || route === 'MUA_XOA') { reply = h.invoiceText(row, route === 'MUA_SUA' ? 'BẠN MUỐN SỬA SỐ TIỀN?' : 'XÁC NHẬN XÓA HÓA ĐƠN?'); route = 'ASK'; }
