function commands(x, h) {
  const admin = x.is_admin === true;
  const buyer = x.is_buyer === true && x.chat_id === x.tg_group_kho_id;
  const body = x.text.replace(/^\/\w+(?:@[A-Za-z0-9_]+)?\s*/, '').trim();
  const result = { ...x, command_type: 'REJECT', reply_text: 'Lệnh chưa được hỗ trợ. Gửi ảnh hóa đơn hoặc dùng /nhapmuatay NCC, số tiền.' };
  if (x.command === '/help') {
    const inKho = x.chat_id === x.tg_group_kho_id;
    const inChu = x.chat_id === x.tg_group_chu_id;
    const inError = x.chat_id === x.tg_group_error_id;
    if (!inKho && !inChu && !inError) return {
      ...result, command_type: 'HELP',
      reply_text: 'ℹ️ /help chỉ dùng trong các group WF04 đã cấu hình.',
    };
    if (!admin && !buyer) return {
      ...result, command_type: 'HELP',
      reply_text: 'Bạn không có quyền sử dụng lệnh WF04. Vui lòng liên hệ quản trị.',
    };
    if (inError) return {
      ...result, command_type: 'HELP',
      reply_text: 'ℹ️ Đây là Group Error, dùng để nhận cảnh báo hệ thống/OCR. Hãy thao tác hóa đơn ở Group Kho và quản lý quỹ ở Group Chủ.',
    };
    const buyerText = buyer ? [
      '<b>HƯỚNG DẪN WF04 — GROUP KHO</b>',
      '• Ảnh đơn: gửi 1 ảnh hóa đơn.',
      '• Batch: chọn 5–10 ảnh rồi nhấn Send một lần; 1 ảnh = 1 hóa đơn.',
      '• <code>/nhapmuatay &lt;NCC&gt;, &lt;số tiền&gt;</code>',
      'Ví dụ: <code>/nhapmuatay Bình Minh, 2350000</code>',
      'Dùng các nút Đúng rồi / Sửa số tiền / Xóa hóa đơn dưới từng kết quả.',
    ] : [];
    const adminText = admin ? [
      '<b>LỆNH ADMIN</b>',
      '• <code>/napquy &lt;số tiền&gt;, &lt;ghi chú&gt;</code>',
      '• <code>/baocaoquy [DD/MM]</code> hoặc <code>/baocaoquy [DD/MM/YYYY]</code>',
      ...(inChu ? ['• /trano — Chọn và trả toàn bộ một hóa đơn công nợ'] : []),
      '/baocaoquy tính lại và gửi báo cáo quỹ đầy đủ cùng các cảnh báo về Group Chủ.',
    ] : [];
    return { ...result, command_type: 'HELP', reply_text: [...buyerText, ...adminText].join('\n') };
  }
  if (x.command === '/trano') {
    if (!admin || !x.tg_group_chu_id || x.chat_id !== x.tg_group_chu_id) return { ...result, reply_text: 'Chỉ Admin được trả nợ tại Group Chủ.' };
    return { ...result, command_type: 'TRANO', page: 0, reply_text: '' };
  }
  if (x.command === '/nhapmuatay') {
    if (!buyer) { result.reply_text = 'Bạn không có quyền nhập mua tay tại nhóm này.'; return result; }
    const split = body.indexOf(',');
    const total = h.amount(split >= 0 ? body.slice(split + 1).trim() : '');
    const vendor = split >= 0 ? body.slice(0, split).trim() : '';
    if (!vendor || !Number.isFinite(total)) { result.reply_text = 'Sai cú pháp. Dùng /nhapmuatay NCC, số tiền. Ví dụ: /nhapmuatay Bình Minh, 2350000 (số tiền >0 và <50.000.000).'; return result; }
    return { ...result, command_type: 'NHAPMUATAY', ncc: h.bounded(vendor), tong_tien: total, reply_text: '' };
  }
  if (x.command === '/napquy') {
    if (!admin) { result.reply_text = 'Bạn không có quyền dùng /napquy.'; return result; }
    let total = h.amount(body, Number.MAX_SAFE_INTEGER);
    let note = '';
    if (!Number.isFinite(total)) {
      // Accept a whole grouped amount first; then split a note at a comma.
      // Reject an ambiguous numeric remainder instead of silently recording 5đ.
      for (let i = body.length - 1; i >= 0; i--) if (body[i] === ',') {
        const left = h.amount(body.slice(0, i).trim(), Number.MAX_SAFE_INTEGER);
        const right = body.slice(i + 1).trim();
        if (Number.isFinite(left) && (right === '' || /[^\d\s.,]/.test(right))) { total = left; note = right; break; }
      }
    }
    if (!Number.isFinite(total)) { result.reply_text = 'Sai cú pháp. Dùng /napquy 5000000, ghi chú. Chỉ nhập số tiền nguyên VNĐ dương.'; return result; }
    return { ...result, command_type: 'NAPQUY', so_tien: total, ghi_chu: h.bounded(note, 500), reply_text: '' };
  }
  if (x.command === '/baocaoquy') {
    if (!admin) { result.reply_text = 'Bạn không có quyền xem báo cáo quỹ.'; return result; }
    const arg = body ? (body.split('/').length === 2 ? body + '/' + h.day().slice(0, 4) : body) : '';
    const date = arg ? h.calendar(arg) : h.day();
    if (arg && !date) { result.reply_text = 'Ngày không hợp lệ. Dùng /baocaoquy DD/MM hoặc DD/MM/YYYY.'; return result; }
    return { ...result, command_type: 'BAOCAO', report_day: date, refresh_start_day: date, reply_text: '' };
  }
  return result;
}
