function splitTelegramLines(lines) {
  if (!Array.isArray(lines) || !lines.length) {
    throw new Error('WF04 report: Missing Telegram message lines.');
  }
  const limit = 3800;
  // The number of chunks cannot exceed the number of lines. Reserve the
  // maximum page-label length before packing, including both page numbers.
  const prefixBudget = 12 + 2 * String(lines.length).length;
  const bodyLimit = limit - prefixBudget;
  const chunks = [];
  let current = [];
  let currentLength = 0;
  for (const line of lines) {
    if (typeof line !== 'string' || line.length > bodyLimit) {
      throw new Error('WF04 report: A Telegram line exceeds the safe message limit.');
    }
    if (current.length && currentLength + 1 + line.length > bodyLimit) {
      chunks.push(current.join('\n'));
      current = [];
      currentLength = 0;
    }
    currentLength += (current.length ? 1 : 0) + line.length;
    current.push(line);
  }
  if (current.length) chunks.push(current.join('\n'));
  // Every HTML tag and escaped entity stays in its original complete line.
  return chunks.length === 1 ? chunks
    : chunks.map((chunk, index) => `(Phần ${index + 1}/${chunks.length})\n${chunk}`);
}
