function debtPage(rows, page, pageSize) {
  const fixedPageSize = 5;
  const requestedPage = Number(page);
  const currentPage = Number.isSafeInteger(requestedPage) && requestedPage >= 0 ? requestedPage : 0;
  const candidates = Array.isArray(rows) ? rows : [];
  const byId = new Map();
  const duplicateIds = new Set();
  for (const row of candidates) {
    const idMua = String(row?.id_mua ?? '');
    if (!/^[A-Za-z0-9_-]{1,50}$/.test(idMua)) continue;
    if (byId.has(idMua)) duplicateIds.add(idMua);
    else byId.set(idMua, row);
  }
  const openDebt = [];
  for (const [idMua, row] of byId) {
    const status = String(row?.trang_thai ?? '').trim().toUpperCase();
    const payment = String(row?.trang_thai_thanh_toan ?? '').trim().toUpperCase();
    const amount = typeof row?.tong_tien === 'number' ? row.tong_tien : Number(row?.tong_tien);
    if (!duplicateIds.has(idMua) && status === 'ACTIVE' && payment === 'CONG_NO_CHUA_TRA'
      && Number.isSafeInteger(amount) && amount > 0) openDebt.push({ row, idMua, amount });
  }
  openDebt.sort((left, right) => {
    const leftDay = String(left.row?.ngay_hach_toan ?? '');
    const rightDay = String(right.row?.ngay_hach_toan ?? '');
    return leftDay.localeCompare(rightDay) || left.idMua.localeCompare(right.idMua);
  });
  const start = currentPage * fixedPageSize;
  const items = openDebt.slice(start, start + fixedPageSize).map(({ row, idMua, amount }) => {
    const day = String(row?.ngay_hach_toan ?? '').replace(/[^0-9-]/g, '').slice(0, 10) || 'Không rõ ngày';
    const supplier = String(row?.ncc ?? 'Không rõ').replace(/[\r\n]+/g, ' ').trim().slice(0, 60) || 'Không rõ';
    return {
      id_mua: idMua,
      ngay_hach_toan: day,
      ncc: supplier,
      tong_tien: amount,
      visible_text: `${day} | ${supplier} | ${amount.toLocaleString('vi-VN')}đ`,
    };
  });
  return {
    page: currentPage,
    page_size: fixedPageSize,
    total: openDebt.length,
    total_pages: Math.ceil(openDebt.length / fixedPageSize),
    items,
  };
}

function prepareDebtPayment(context, rows, now) {
  const noPayment = { can_pay: false, patch: null };
  const chatId = String(context?.chat_id ?? '').trim();
  const groupChuId = String(context?.tg_group_chu_id ?? '').trim();
  if (!context?.is_admin || !chatId || !groupChuId || chatId !== groupChuId) return noPayment;
  const idMua = String(context.id_mua ?? '');
  if (!/^[A-Za-z0-9_-]{1,50}$/.test(idMua) || !Array.isArray(rows)) return noPayment;
  const matches = rows.filter(row => String(row?.id_mua ?? '') === idMua);
  if (matches.length !== 1) return noPayment;
  const row = matches[0];
  const status = String(row?.trang_thai ?? '').trim().toUpperCase();
  const payment = String(row?.trang_thai_thanh_toan ?? '').trim().toUpperCase();
  if (status !== 'ACTIVE' || payment !== 'CONG_NO_CHUA_TRA') return noPayment;
  const instant = new Date(now);
  if (Number.isNaN(instant.getTime())) return noPayment;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(instant);
  const part = type => parts.find(item => item.type === type)?.value;
  const day = `${part('year')}-${part('month')}-${part('day')}`;
  return {
    can_pay: true,
    patch: {
      id_mua: idMua,
      trang_thai_thanh_toan: 'CONG_NO_DA_TRA',
      ngay_tra_no: day,
      nguoi_tra_no: String(context.user_id ?? ''),
      thoi_gian_tra_no: instant.toISOString(),
    },
  };
}

function buildDebtPage(x, rows, h) {
  if (x.is_admin !== true || !x.tg_group_chu_id || x.chat_id !== x.tg_group_chu_id) return { ...x, debt_exists: false, debt_route: 'REPLY', reply_text: 'Chỉ Admin được trả nợ tại Group Chủ.' };
  let page = debtPage(rows, x.page || 0, 5);
  // A stale last-page button still opens a usable current page after debts close.
  if (page.total && !page.items.length) page = debtPage(rows, Math.min(9999, page.total_pages - 1), 5);
  const previous = page.page > 0;
  const next = page.page + 1 < page.total_pages && page.page < 9999;
  return { ...x, debt_page: page, debt_exists: page.items.length > 0, debt_route: page.items.length ? 'PAGE' : 'REPLY',
    debt_layout: page.items.length + '_' + (previous ? 'P' : '') + (next ? 'N' : ''),
    reply_text: page.items.length ? '<b>CÔNG NỢ CHƯA TRẢ</b>\nTrang ' + (page.page + 1) + '/' + page.total_pages + '\nChọn một hóa đơn để trả toàn bộ.' : 'Hiện không có hóa đơn công nợ hợp lệ chưa trả.' };
}

