  return '<b>' + title + '</b>\nNgày hạch toán: ' + safe(row.ngay_hach_toan, 10) + '\nNCC: ' + safe(row.ncc)
    + '\nSố tiền: ' + h.money(row.tong_tien) + 'đ\nTrạng thái: ' + state
