const PAYMENT_STATES = {"WAITING":"CHO_PHAN_LOAI","PAID":"DA_THANH_TOAN","DEBT_OPEN":"CONG_NO_CHUA_TRA","DEBT_PAID":"CONG_NO_DA_TRA"};
function common() {
  const html = value => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const bounded = (value, size = 300) => String(value ?? '').slice(0, size);
  const money = value => Number(value).toLocaleString('vi-VN');
  function amount(value, upper = 50000000) {
    let n = value;
    if (typeof value === 'string') {
      const s = value.trim().replace(/\s*(?:vnđ|vnd|đ|₫)\s*$/i, '').trim();
      if (!/^(?:\d+|\d{1,3}(?:[., ]\d{3})+)$/.test(s)) return NaN;
      n = Number(s.replace(/[., ]/g, ''));
    }
    return Number.isSafeInteger(n) && n > 0 && n < upper ? n : NaN;
  }
