      .replace(/AIza[A-Za-z0-9_-]{20,}/g, '[API_KEY_REDACTED]')
      .replace(/(x-goog-api-key|authorization)(["'\s:=]+)[^\s,"'}]+/gi, '$1$2[REDACTED]');
