      const date = new Date(Date.UTC(y, m - 1, d));
      return y > 1900 && date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d ? [y, String(m).padStart(2, '0'), String(d).padStart(2, '0')].join('-') : null;
