  if (!['CHO_PHAN_LOAI', 'DA_THANH_TOAN', 'CONG_NO_CHUA_TRA', 'CONG_NO_DA_TRA'].includes(value)) return 'INVALID';
  return value;
}

function calculateFund(config, muaRows, napRows, summaryRows) {
  const today = calendarDay(config?.ngay, 'config.ngay');
  const initial = integerVnd(config?.quy_ban_dau, 'config.quy_ban_dau');
  const minimum = integerVnd(config?.nguong_quy_an_toan, 'config.nguong_quy_an_toan');
  const largeThreshold = integerVnd(config?.nguong_hoa_don_lon, 'config.nguong_hoa_don_lon');
  const add = (left, right) => {
    const result = left + right;
    if (!Number.isSafeInteger(result)) {
      throw new Error('WF04 report: Daily monetary total exceeds the safe integer range.');
    }
    return result;
  };
  const normalized = row => ({
    id_mua: String(row.id_mua ?? '').trim(),
    ngay: calendarDay(row.ngay, 'LOG_MUA.ngay'),
    ncc: String(row.ncc ?? '').trim() || 'Không rõ',
    nguoi_mua: String(row.nguoi_mua ?? '').trim() || 'Không rõ',
    thoi_gian: String(row.thoi_gian ?? '').trim(),
    link_anh: String(row.link_anh ?? '').trim(),
    do_tin_cay_ocr: String(row.do_tin_cay_ocr ?? ''),
  });

  const paidPurchases = [];
  const debtIncurred = [];
  const debtPaid = [];
  const outstandingDebt = [];
  const waitingInvoices = [];
  const largeInvoices = [];
  const seenPurchaseIds = new Set();
  for (const row of nonEmptyRows(muaRows, 'LOG_MUA')) {
    if (String(row.trang_thai ?? '').trim().toUpperCase() !== 'ACTIVE') continue;
    const purchaseId = String(row.id_mua ?? '').trim();
    if (!/^[A-Za-z0-9_-]{1,50}$/.test(purchaseId)) {
      throw new Error('WF04 report: Invalid identifier in LOG_MUA.id_mua.');
    }
    if (seenPurchaseIds.has(purchaseId)) {
      throw new Error('WF04 report: Duplicate LOG_MUA.id_mua rows; resolve duplicates before reporting.');
    }
    seenPurchaseIds.add(purchaseId);
    const paymentState = effectivePaymentState(row);
    if (paymentState === 'INVALID') {
      throw new Error('WF04 report: Invalid payment state in LOG_MUA.trang_thai_thanh_toan.');
    }
    const base = normalized(row);
    const isLegacy = String(row.trang_thai_thanh_toan ?? '').trim() === '';
    let accountingDay = '';
    let paymentDay = '';
    if (isLegacy) accountingDay = base.ngay;
    else if (paymentState !== PAYMENT_STATES.WAITING) {
      accountingDay = calendarDay(row.ngay_hach_toan, 'LOG_MUA.ngay_hach_toan');
    }
    if (paymentState === PAYMENT_STATES.DEBT_PAID) {
      paymentDay = calendarDay(row.ngay_tra_no, 'LOG_MUA.ngay_tra_no');
      if (paymentDay < accountingDay) {
        throw new Error('WF04 report: LOG_MUA.ngay_tra_no cannot precede LOG_MUA.ngay_hach_toan.');
      }
    }

    const paidToday = paymentState === PAYMENT_STATES.PAID && accountingDay === today;
    const incurredToday = (paymentState === PAYMENT_STATES.DEBT_OPEN
      || paymentState === PAYMENT_STATES.DEBT_PAID) && accountingDay === today;
    const paidDebtToday = paymentState === PAYMENT_STATES.DEBT_PAID && paymentDay === today;
    const remainsOutstanding = accountingDay && accountingDay <= today
      && (paymentState === PAYMENT_STATES.DEBT_OPEN
        || (paymentState === PAYMENT_STATES.DEBT_PAID && paymentDay > today));
    const remainsWaiting = paymentState === PAYMENT_STATES.WAITING && base.ngay <= today;
    const isLargeToday = base.ngay === today;
    if (!(paidToday || incurredToday || paidDebtToday || remainsOutstanding || remainsWaiting || isLargeToday)) continue;

    const amount = integerVnd(row.tong_tien, 'LOG_MUA.tong_tien', 1);
    const item = {
      ...base, tong_tien: amount, trang_thai_thanh_toan: paymentState,
      ngay_hach_toan: accountingDay, ngay_tra_no: paymentDay, legacy: isLegacy,
    };
    if (paidToday) paidPurchases.push(item);
    if (incurredToday) debtIncurred.push(item);
    if (paidDebtToday) debtPaid.push(item);
    if (remainsOutstanding) outstandingDebt.push(item);
    if (remainsWaiting) waitingInvoices.push(item);
    if (isLargeToday && amount > largeThreshold) largeInvoices.push(item);
  }
  outstandingDebt.sort((left, right) => left.ngay_hach_toan.localeCompare(right.ngay_hach_toan)
    || left.id_mua.localeCompare(right.id_mua));
  waitingInvoices.sort((left, right) => left.ngay.localeCompare(right.ngay)
    || left.id_mua.localeCompare(right.id_mua));

  const deposits = nonEmptyRows(napRows, 'LOG_NAP')
    .filter(row => calendarDay(row.ngay, 'LOG_NAP.ngay') === today)
    .map(row => integerVnd(row.so_tien, 'LOG_NAP.so_tien', 1));
  const datedSummaries = nonEmptyRows(summaryRows, 'TONGHOP')
    .map(row => ({ row, day: calendarDay(row.ngay, 'TONGHOP.ngay') }));
  const seenSummaryDays = new Set();
  for (const entry of datedSummaries) {
    if (seenSummaryDays.has(entry.day)) {
      throw new Error('WF04 report: Duplicate TONGHOP.ngay rows; resolve duplicates before reporting.');
    }
    seenSummaryDays.add(entry.day);
  }
  const previous = datedSummaries.filter(entry => entry.day < today)
    .sort((left, right) => right.day.localeCompare(left.day));
  const current = datedSummaries.find(entry => entry.day === today);
  const opening = previous.length
    ? integerVnd(previous[0].row.quy_con_lai, 'TONGHOP.quy_con_lai', -Number.MAX_SAFE_INTEGER)
    : initial;
  const currentExpense = current?.row.chi_tieu_khac;
  const hasCurrentExpense = currentExpense !== undefined && currentExpense !== null
    && String(currentExpense).trim() !== '';
  const otherExpense = integerVnd(hasCurrentExpense ? currentExpense : config.chi_tieu_khac,
    hasCurrentExpense ? 'TONGHOP.chi_tieu_khac' : 'config.chi_tieu_khac');
  const total = items => items.reduce((sum, row) => add(sum, row.tong_tien), 0);
  const totalPaidPurchases = total(paidPurchases);
  const totalDeposits = deposits.reduce(add, 0);
  const totalDebtIncurred = total(debtIncurred);
  const totalDebtPayments = total(debtPaid);
  const totalOutstandingDebt = total(outstandingDebt);
  const totalWaiting = total(waitingInvoices);
  const remaining = add(add(add(add(opening, -totalPaidPurchases), totalDeposits), -otherExpense), -totalDebtPayments);
  return {
    ...config,
    ngay: today,
    nguong_quy_an_toan: minimum,
    nguong_hoa_don_lon: largeThreshold,
    // n8n matches a Sheet date by its displayed string. Preserve that exact key
    // on reruns while using the canonical local day for all calculations.
    tonghop_ngay: current ? String(current.row.ngay) : today,
    quy_ton_hom_truoc: opening,
    tong_mua_hom_nay: totalPaidPurchases,
    tong_nap_hom_nay: totalDeposits,
    chi_tieu_khac: otherExpense,
    quy_con_lai: remaining,
    co_canh_bao: remaining < minimum ? '🔴' : '🟢',
    tong_cong_no_phat_sinh_hom_nay: totalDebtIncurred,
    tong_tra_no_hom_nay: totalDebtPayments,
    tong_cong_no_con_lai: totalOutstandingDebt,
    so_hoa_don_cho_phan_loai: waitingInvoices.length,
    tong_tien_cho_phan_loai: totalWaiting,
    canh_bao_quy: remaining < minimum,
    canh_bao_hoa_don_lon: largeInvoices.length > 0,
    hoa_don: paidPurchases,
    cong_no_phat_sinh_hom_nay: debtIncurred,
    cong_no_da_tra_hom_nay: debtPaid,
    cong_no_con_lai: outstandingDebt,
    hoa_don_cho_phan_loai: waitingInvoices,
    hoa_don_lon: largeInvoices,
  };
}

function recalculateSummaryChain(config, muaRows, napRows, summaryRows, startDay, endDay) {
  const firstDay = calendarDay(startDay, 'startDay');
  const lastDay = calendarDay(endDay, 'endDay');
  if (firstDay > lastDay) throw new Error('WF04 report: startDay cannot be after endDay.');
  const summaries = nonEmptyRows(summaryRows, 'TONGHOP');
  const byDay = new Map();
  for (const row of summaries) {
    const day = calendarDay(row.ngay, 'TONGHOP.ngay');
    if (byDay.has(day)) {
      throw new Error('WF04 report: Duplicate TONGHOP.ngay rows; resolve duplicates before recalculation.');
    }
    byDay.set(day, { ...row });
  }
  const days = new Set([firstDay, lastDay]);
  for (const day of byDay.keys()) if (day >= firstDay && day <= lastDay) days.add(day);
  const result = [];
  for (const day of [...days].sort()) {
    const calculated = calculateFund({ ...config, ngay: day }, muaRows, napRows, [...byDay.values()]);
    const row = Object.fromEntries(TONGHOP_COLUMNS.map(column => [column,
      column === 'ngay' ? calculated.tonghop_ngay : calculated[column]]));
    byDay.set(day, row);
    result.push(row);
  }
  return result;
}
