function integerVnd(value, field, minimum = 0) {
  const invalid = () => { throw new Error(`WF04 report: Invalid integer VND in ${field}.`); };
  let amount;
  if (typeof value === 'number') amount = value;
  else if (typeof value === 'string') {
    let text = value.replace(/[\u00a0\u202f]/g, ' ').trim()
      .replace(/^(?:VND|VNĐ|₫|đ)\s*/i, '').replace(/\s*(?:VND|VNĐ|₫|đ)$/i, '').trim();
    const sign = text.startsWith('-') ? -1 : 1;
    text = text.replace(/^[+-]/, '');
    let digits;
    if (/^\d+$/.test(text)) digits = text;
    else if (/^\d+[.,]0{1,2}$/.test(text)) digits = text.replace(/[.,]0{1,2}$/, '');
    else if (/^\d{1,3}(?:\.\d{3})+(?:,0{1,2})?$/.test(text)) {
      digits = text.replace(/,0{1,2}$/, '').replace(/\./g, '');
    } else if (/^\d{1,3}(?:,\d{3})+(?:\.0{1,2})?$/.test(text)) {
      digits = text.replace(/\.0{1,2}$/, '').replace(/,/g, '');
    } else if (/^\d{1,3}(?: \d{3})+(?:[.,]0{1,2})?$/.test(text)) {
      digits = text.replace(/[.,]0{1,2}$/, '').replace(/ /g, '');
    } else return invalid();
    amount = sign * Number(digits);
  } else return invalid();
  if (!Number.isSafeInteger(amount) || amount < minimum) return invalid();
  return amount;
}

function nonEmptyRows(rows, sheet) {
  if (!Array.isArray(rows)) throw new Error(`WF04 report: Invalid row collection in ${sheet}.`);
  return rows.filter(row => {
    if (!row || typeof row !== 'object' || Array.isArray(row)) {
      throw new Error(`WF04 report: Invalid row data in ${sheet}.`);
    }
    if (row.error) throw new Error(`WF04 report: Failed read from ${sheet}.`);
    return Object.entries(row).some(([key, value]) => key !== 'row_number'
      && value !== null && value !== undefined && String(value).trim() !== '');
  });
}

