  const debtIncurred = [];
  const debtPaid = [];
  const outstandingDebt = [];
  const waitingInvoices = [];
  const largeInvoices = [];
  const seenPurchaseIds = new Set();
  for (const row of nonEmptyRows(muaRows, 'LOG_MUA')) {
    if (String(row.trang_thai ?? '').trim().toUpperCase() !== 'ACTIVE') continue;
    const purchaseId = String(row.id_mua ?? '').trim();
    if (!/^[A-Za-z0-9_-]{1,50}$/.test(purchaseId)) {
      throw new Error('WF04 report: Invalid identifier in LOG_MUA.id_mua.');
    }
    if (seenPurchaseIds.has(purchaseId)) {
