    const calculated = calculateFund({ ...config, ngay: day }, muaRows, napRows, [...byDay.values()]);
    const row = Object.fromEntries(TONGHOP_COLUMNS.map(column => [column,
      column === 'ngay' ? calculated.tonghop_ngay : calculated[column]]));
    byDay.set(day, row);
