    || left.id_mua.localeCompare(right.id_mua));
  waitingInvoices.sort((left, right) => left.ngay.localeCompare(right.ngay)
    || left.id_mua.localeCompare(right.id_mua));

  const deposits = nonEmptyRows(napRows, 'LOG_NAP')
    .filter(row => calendarDay(row.ngay, 'LOG_NAP.ngay') === today)
    .map(row => integerVnd(row.so_tien, 'LOG_NAP.so_tien', 1));
  const datedSummaries = nonEmptyRows(summaryRows, 'TONGHOP')
    .map(row => ({ row, day: calendarDay(row.ngay, 'TONGHOP.ngay') }));
  const seenSummaryDays = new Set();
  for (const entry of datedSummaries) {
    if (seenSummaryDays.has(entry.day)) {
