  const current = datedSummaries.find(entry => entry.day === today);
  const opening = previous.length
    ? integerVnd(previous[0].row.quy_con_lai, 'TONGHOP.quy_con_lai', -Number.MAX_SAFE_INTEGER)
    : initial;
  const currentExpense = current?.row.chi_tieu_khac;
