  const totalPaidPurchases = total(paidPurchases);
  const totalDeposits = deposits.reduce(add, 0);
  const totalDebtIncurred = total(debtIncurred);
  const totalDebtPayments = total(debtPaid);
  const totalOutstandingDebt = total(outstandingDebt);
  const totalWaiting = total(waitingInvoices);
