    tong_nap_hom_nay: totalDeposits,
    chi_tieu_khac: otherExpense,
    quy_con_lai: remaining,
    co_canh_bao: remaining < minimum ? '🔴' : '🟢',
    tong_cong_no_phat_sinh_hom_nay: totalDebtIncurred,
    tong_tra_no_hom_nay: totalDebtPayments,
    tong_cong_no_con_lai: totalOutstandingDebt,
    so_hoa_don_cho_phan_loai: waitingInvoices.length,
    tong_tien_cho_phan_loai: totalWaiting,
    canh_bao_quy: remaining < minimum,
    canh_bao_hoa_don_lon: largeInvoices.length > 0,
    hoa_don: paidPurchases,
    cong_no_phat_sinh_hom_nay: debtIncurred,
    cong_no_da_tra_hom_nay: debtPaid,
    cong_no_con_lai: outstandingDebt,
    hoa_don_cho_phan_loai: waitingInvoices,
