}

function recalculateSummaryChain(config, muaRows, napRows, summaryRows, startDay, endDay) {
  const firstDay = calendarDay(startDay, 'startDay');
  const lastDay = calendarDay(endDay, 'endDay');
  if (firstDay > lastDay) throw new Error('WF04 report: startDay cannot be after endDay.');
  const summaries = nonEmptyRows(summaryRows, 'TONGHOP');
  const byDay = new Map();
  for (const row of summaries) {
    const day = calendarDay(row.ngay, 'TONGHOP.ngay');
    if (byDay.has(day)) {
      throw new Error('WF04 report: Duplicate TONGHOP.ngay rows; resolve duplicates before recalculation.');
    }
    byDay.set(day, { ...row });
  }
  const days = new Set([firstDay, lastDay]);
  for (const day of byDay.keys()) if (day >= firstDay && day <= lastDay) days.add(day);
  const result = [];
  for (const day of [...days].sort()) {
    const calculated = calculateFund({ ...config, ngay: day }, muaRows, napRows, [...byDay.values()]);
    const row = Object.fromEntries(TONGHOP_COLUMNS.map(column => [column,
      column === 'ngay' ? calculated.tonghop_ngay : calculated[column]]));
    byDay.set(day, row);
    result.push(row);
  }
  return result;
}
